  // Inilah "Seller Impulse Absorb by Buyer" pada kerangka aslinya.
  var ABS = [];
  for (i = 0; i < N; i++) {
    var a5 = ATR14[i], v5 = VMED[i];
    if (!(a5 > 0) || !(v5 > 0) || i < 1) { ABS.push(false); continue; }
    var pc5 = C[i - 1], rng5 = H[i] - L[i];
    var posT = rng5 > 0 ? (C[i] - L[i]) / rng5 : 0.5;
    ABS.push((pc5 - L[i]) >= a5 && C[i] >= pc5 - 0.2 * a5 && posT >= 0.6 && V[i] >= 1.5 * v5);
  }
