      s += `<rect class="${cls}" x="${x.toFixed(1)}" y="${yy.toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(0, h - 1).toFixed(1)}"><title>${fmt(v.m)} · ${k === 'ritel' ? 'ritel lokal' : k === 'inst' ? 'institusi lokal' : 'asing'} ${v[k].toFixed(1)}%</title></rect>`;
