  const lembar = v => v == null ? '–' : v >= 1e9 ? (v / 1e9).toFixed(2) + ' M' : v >= 1e6 ? (v / 1e6).toFixed(1) + ' jt' : Math.round(v).toLocaleString('id-ID');
